GRAM = [
("A2", "명령형 + 대명사 — Mets-la de côté, dis-lui", "« Mets-la de côté. » « Dis-lui la vérité. » « Envoie-la. » 긍정 명령형에서는 대명사가 동사 뒤에 하이픈으로 붙는다. 부정이면 앞으로: « Ne la jette pas. »"),
("B1", "서수 나열 — Un, deux, trois", "« Un : on dresse à la même minute. » « Deux : chaque assiette passe devant moi. » « Trois : si vous avez un doute, vous demandez. » 지시를 번호로 끊으면 120명 규모의 현장에서도 전달이 쉬워진다."),
("B1", "현재형 명령 — vous demandez, on dresse", "« On dresse à la même minute. » « Vous demandez. » 프랑스어 지시는 명령형 외에 현재형으로도 한다. 더 부드럽지만 분명한 지시 방식. 격식 상황에서 흔하다."),
("B2", "il faut que + 접속법", "« Il faut que ce soit sans farine. » ce soit(être)는 접속법. 필요·의무를 나타내는 il faut que 뒤에는 항상 접속법. 일상에서는 단순히 « Faut que ça soit... » 로 줄인다."),
("B2", "조건 표현 — à condition de + 부정사", "« À condition de remettre tout en place avant minuit. » 조건을 붙일 때 쓰는 격식 표현. 주어가 같으면 de + 부정사, 다르면 à condition que + 접속법."),
("B2", "Je préfère A à B", "« Je préfère une promesse tenue à une promesse faite. » préférer A à B 는 'B보다 A가 좋다'. 같은 문형에 plutôt que 를 쓸 수도 있다."),
("C1", "정중한 요청과 격식 — permettez-moi de + 부정사", "« Permettez-moi de vous féliciter. » « Je vous prie de… » 격식 있는 말투. 연회·호텔 같은 자리에서 쓴다. 가까운 사이에는 « Je tiens à te féliciter. »"),
]

